import React, { useState, useRef, useEffect } from 'react';

const AmbientSound = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef(null);
  const [volume, setVolume] = useState(0.2); // مستوى صوت منخفض افتراضياً لعدم الإزعاج

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  useEffect(() => {
    // محاولة التشغيل التلقائي عند فتح الموقع
    const attemptAutoplay = async () => {
      if (audioRef.current) {
        try {
          await audioRef.current.play();
          setIsPlaying(true);
        } catch (error) {
          // إذا منع المتصفح التشغيل التلقائي، ننتظر أول تفاعل (نقرة) من المستخدم
          const enableAudio = () => {
            audioRef.current.play().then(() => setIsPlaying(true)).catch(() => {});
            document.removeEventListener('click', enableAudio);
          };
          document.addEventListener('click', enableAudio);
        }
      }
    };
    attemptAutoplay();
  }, []);

  const togglePlay = () => {
    if (!audioRef.current) return;
    
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      const playPromise = audioRef.current.play();
      if (playPromise !== undefined) {
        playPromise.catch(error => {
          console.log("Audio play prevented:", error);
        });
      }
    }
    setIsPlaying(!isPlaying);
  };

  return (
    <div 
      className="position-fixed bottom-0 start-0 m-3 p-2 bg-white rounded-pill shadow-lg d-flex align-items-center" 
      style={{ zIndex: 9999, border: '2px solid #0d6efd', cursor: 'pointer' }}
    >
      <audio ref={audioRef} loop onError={(e) => console.error("Audio load error:", e)}>
        <source src="https://upload.wikimedia.org/wikipedia/commons/e/e7/Erik_Satie_-_Gymnop%C3%A9die_No._1.ogg" type="audio/ogg" />
        <source src="https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e7/Erik_Satie_-_Gymnop%C3%A9die_No._1.ogg/Erik_Satie_-_Gymnop%C3%A9die_No._1.ogg.mp3" type="audio/mp3" />
      </audio>
      
      <button 
        className={`btn btn-sm rounded-circle ${isPlaying ? 'btn-primary' : 'btn-secondary'} me-2`}
        onClick={(e) => { e.stopPropagation(); togglePlay(); }}
        style={{ width: 36, height: 36, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
      >
        {isPlaying ? '🔊' : '🔇'}
      </button>
      
      <div className="d-flex flex-column justify-content-center" style={{marginRight: '5px'}}>
         <span className="fw-bold text-dark" style={{fontSize: '0.75rem'}}>موسيقى</span>
         {isPlaying && (
            <input 
              type="range" 
              min="0" 
              max="1" 
              step="0.05" 
              value={volume} 
              onChange={(e) => setVolume(parseFloat(e.target.value))}
              style={{ width: '60px', height: '4px', marginTop: '2px' }} 
            />
         )}
      </div>
    </div>
  );
};

export default AmbientSound;
